const out = [];

// take the first (and usually only) incoming item from the upload form
const item = items[0];

// all uploaded files live in item.binary
const binaries = item.binary || {};

for (const key of Object.keys(binaries)) {
  const file = binaries[key];

  out.push({
    json: {
      originalKey: key,
      filename: file.fileName || key,
    },
    binary: {
      // normalize each file to a single binary key: "data"
      data: file,
    },
  });
}

return out;

// ============================================================
// Generic 3GPP PDF text cleaner + metadata extractor + clause-per-chunk splitter
// For ETSI/3GPP TS/TR PDFs
// ============================================================

// -------------------- helpers --------------------
function normalizeText(s) {
  return (s || "")
    .replace(/\r\n/g, "\n")
    .replace(/\u00a0/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\f/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function safeTrim(s) {
  return typeof s === "string" ? s.trim() : s;
}

function escapeRegex(s) {
  return (s || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function uniqBy(arr, keyFn) {
  const seen = new Set();
  const out = [];
  for (const x of arr) {
    const k = keyFn(x);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(x);
  }
  return out;
}

// -------------------- metadata extraction --------------------
/**
 * Extract generic 3GPP metadata from the first part of raw text.
 *
 * Supports patterns like:
 *   3GPP TS 33.501 version 18.9.0 Release 18
 *   3GPP TR 33.926 version 17.4.0 Release 17
 *   ETSI TS 133 501 V18.9.0 (2025-04)
 */
function extract3gppMetaFromFirstChars(rawText, firstN = 4000) {
  const head = (rawText || "").replace(/\r\n/g, "\n").slice(0, firstN);

  let spec_type = null;
  let spec_number = null;
  let version = null;
  let release = null;
  let spec = null;
  let etsi_doc = null;
  let title = null;

  const mainMatch = head.match(
    /\b3GPP\s+(TS|TR)\s+(\d{2}\.\d{3})\s+version\s+(\d+\.\d+\.\d+)\s+Release\s+(\d+)\b/i
  );

  if (mainMatch) {
    spec_type = (mainMatch[1] || "").toUpperCase();
    spec_number = mainMatch[2] || null;
    version = mainMatch[3] || null;
    release = mainMatch[4] ? `Rel-${mainMatch[4]}` : null;
    spec = `3GPP ${spec_type} ${spec_number}`;
  }

  const etsiMatch = head.match(
    /\bETSI\s+(TS|TR)\s+(\d{3})\s+(\d{3})\s+V(\d+\.\d+\.\d+)\b/i
  );
  if (etsiMatch) {
    etsi_doc = `ETSI ${(etsiMatch[1] || "").toUpperCase()} ${etsiMatch[2]} ${etsiMatch[3]} V${etsiMatch[4]}`;
  }

  const lines = head.split("\n").map(x => x.trim()).filter(Boolean);

  const idx3gpp = lines.findIndex(line =>
    /3GPP\s+(TS|TR)\s+\d{2}\.\d{3}\s+version\s+\d+\.\d+\.\d+\s+Release\s+\d+/i.test(line)
  );

  if (idx3gpp > 0) {
    const candidateLines = [];
    for (let i = Math.max(0, idx3gpp - 4); i < idx3gpp; i++) {
      const line = lines[i];
      if (!line) continue;
      if (/^ETSI\s+(TS|TR)\b/i.test(line)) continue;
      if (/^TECHNICAL\s+(SPECIFICATION|REPORT)\b/i.test(line)) continue;
      if (/^(5G|LTE|NR|NG-RAN|E-UTRAN|UTRAN|GERAN)\s*;?$/i.test(line)) continue;
      if (/^\(?3GPP\s+(TS|TR)\b/i.test(line)) continue;
      if (/^version\b/i.test(line)) continue;
      candidateLines.push(line.replace(/\s*;\s*$/, ""));
    }
    if (candidateLines.length) {
      title = candidateLines.join(" ").replace(/\s{2,}/g, " ").trim();
    }
  }

  return {
    source_type: "3gpp_spec",
    spec_type,
    spec_number,
    spec,
    version,
    release,
    etsi_doc,
    title,
    meta_extracted_from: `first_${firstN}_chars`,
  };
}

// -------------------- cleanup --------------------
function remove3gppRunningHeadersAndFooters(text) {
  if (typeof text !== "string") return text;
  let t = text.replace(/\r\n/g, "\n");

  // Standalone ETSI line
  t = t.replace(/\n\s*ETSI\s*\n/gi, "\n");

  // Common repeated running header/footer:
  // 3GPP TS 33.501 version 18.9.0 Release 18 10 ETSI TS 133 501 V18.9.0 (2025-04)
  t = t.replace(
    /\n\s*3GPP\s+(?:TS|TR)\s+\d{2}\.\d{3}\s+version\s+\d+\.\d+\.\d+\s+Release\s+\d+\s+\d{1,4}\s+ETSI\s+(?:TS|TR)\s+\d{3}\s+\d{3}\s+V\d+\.\d+\.\d+\s*\(\d{4}-\d{2}\)\s*\n/gi,
    "\n"
  );

  // Looser spacing variant
  t = t.replace(
    /\n\s*3GPP\s+(?:TS|TR)\s+\d{2}\.\d{3}[\s\S]{0,80}?Release\s+\d+[\s\S]{0,50}?ETSI\s+(?:TS|TR)\s+\d{3}\s+\d{3}\s+V\d+\.\d+\.\d+[\s\S]{0,20}?\n/gi,
    "\n"
  );

  // Common legal leftovers
  t = t.replace(/\n\s*©\s*ETSI\s+\d{4}\s*\.?\s*\n/gi, "\n");
  t = t.replace(/\n\s*All rights reserved\.?\s*\n/gi, "\n");

  // Bare page number lines
  t = t.replace(/\n\s*\d{1,4}\s*\n/g, "\n");

  return normalizeText(t);
}

function dropFrontMatter(text) {
  const m = text.match(/(?:^|\n)1\s+Scope\s*(?:\n|$)/i);
  if (!m) return text;
  return text.slice(m.index).trim();
}

function removeResidualBoilerplate(text) {
  let t = text;

  const junkHeadings = [
    "Intellectual Property Rights",
    "Legal Notice",
    "Modal verbs terminology",
    "Foreword",
  ];

  for (const heading of junkHeadings) {
    const re = new RegExp(`\\n\\s*${escapeRegex(heading)}\\s*\\n`, "gi");
    t = t.replace(re, "\n");
  }

  return normalizeText(t);
}

// -------------------- heading detection --------------------
/**
 * Matches 3GPP clause headings such as:
 *   1 Scope
 *   3 Definitions and abbreviations
 *   3.1 Definitions
 *   6.1.3.2 Authentication procedure for 5G AKA
 *   7A Security for trusted non-3GPP access ...
 *   5.8a Requirements on AUSF
 */
const CLAUSE_HEADING_RE =
  /(^|\n)((?:\d+[A-Za-z]?)(?:\.\d+[A-Za-z]?){0,8})\s+([A-Z][^\n]{2,220})\s*(?=\n)/g;

/**
 * Matches annex headings such as:
 *   Annex A (normative): Title
 *   Annex B (informative) Title
 *   Annex C: Title
 *   Annex D
 */
const ANNEX_HEADING_RE =
  /(^|\n)(Annex\s+[A-Z]{1,3})\s*(?:\((normative|informative)\))?\s*:?\s*([^\n]{0,220})\s*(?=\n)/gi;

function splitByHeadings(text) {
  const markers = [];

  CLAUSE_HEADING_RE.lastIndex = 0;
  for (let m; (m = CLAUSE_HEADING_RE.exec(text)) !== null;) {
    const start = m.index + (m[1] ? m[1].length : 0);
    const clause = safeTrim(m[2]);
    const title = safeTrim(m[3]);

    if (!clause || !title) continue;
    if (/\.{5,}/.test(title)) continue; // likely TOC leader dots
    if (/^\d+\s*$/.test(title)) continue;
    if (/^(ETSI|Contents)$/i.test(title)) continue;

    markers.push({
      start,
      type: "clause",
      clause,
      title,
    });
  }

  ANNEX_HEADING_RE.lastIndex = 0;
  for (let m; (m = ANNEX_HEADING_RE.exec(text)) !== null;) {
    const start = m.index + (m[1] ? m[1].length : 0);

    markers.push({
      start,
      type: "annex",
      annex: safeTrim(m[2]),
      annex_type: safeTrim((m[3] || "").toLowerCase()) || null,
      title: safeTrim(m[4]) || null,
    });
  }

  if (!markers.length) {
    return [{ header: null, body: text }];
  }

  const deduped = uniqBy(
    markers.sort((a, b) => a.start - b.start),
    m => `${m.start}|${m.type}|${m.clause || ""}|${m.annex || ""}|${m.title || ""}`
  );

  const sections = [];
  for (let i = 0; i < deduped.length; i++) {
    const cur = deduped[i];
    const nextStart = i + 1 < deduped.length ? deduped[i + 1].start : text.length;
    let body = text.slice(cur.start, nextStart).trim();

    // If annex title missing, infer from following line if possible
    if (cur.type === "annex" && (!cur.title || cur.title.length < 3)) {
      const lines = body.split("\n").map(x => x.trim()).filter(Boolean);
      if (lines.length >= 2) {
        const candidate = lines[1];
        if (
          candidate &&
          candidate.length >= 3 &&
          !/^\d+([.]\d+)*[A-Za-z]?\s+/.test(candidate) &&
          !/^Annex\s+[A-Z]{1,3}/i.test(candidate)
        ) {
          cur.title = candidate;
        }
      }
    }

    const header =
      cur.type === "clause"
        ? { type: "clause", clause: cur.clause, title: cur.title }
        : { type: "annex", annex: cur.annex, annex_type: cur.annex_type, title: cur.title };

    sections.push({ header, body });
  }

  return sections;
}

// -------------------- clause-per-chunk sizing --------------------
/**
 * Keeps each detected section as its own chunk.
 * Only splits when ONE section is itself too large.
 */
function splitLargeSection(body, maxChars = 4500, overlapChars = 250) {
  if (!body || body.length <= maxChars) return [body];

  const parts = [];
  let start = 0;

  while (start < body.length) {
    let end = Math.min(body.length, start + maxChars);

    if (end < body.length) {
      const paraBreak = body.lastIndexOf("\n\n", end);
      const lineBreak = body.lastIndexOf("\n", end);
      const sentenceBreak = Math.max(
        body.lastIndexOf(". ", end),
        body.lastIndexOf("; ", end)
      );

      let candidate = -1;
      if (paraBreak > start + 500) candidate = paraBreak;
      else if (lineBreak > start + 500) candidate = lineBreak;
      else if (sentenceBreak > start + 500) candidate = sentenceBreak + 1;

      if (candidate > start) end = candidate;
    }

    parts.push(body.slice(start, end).trim());
    if (end >= body.length) break;

    start = Math.max(0, end - overlapChars);
  }

  return parts.filter(Boolean);
}

function sizeControl(
  sections,
  { maxChars = 4500, overlapChars = 250 } = {}
) {
  const final = [];

  for (const sec of sections) {
    if (!sec.body || !sec.body.trim()) continue;

    if (sec.body.length <= maxChars) {
      final.push(sec);
      continue;
    }

    const splits = splitLargeSection(sec.body, maxChars, overlapChars);
    for (const piece of splits) {
      final.push({
        header: sec.header,
        body: piece,
      });
    }
  }

  return final;
}

// -------------------- heading-only parent chunk filter --------------------
/**
 * Returns true for chunks that are only the heading line with no real body.
 * Example:
 *   5.3 Requirements on the gNB
 *
 * This lets you skip empty container clauses while keeping real subclauses
 * like 5.3.1 and 5.3.2.
 */
function isHeadingOnlyClauseChunk(body, clause) {
  if (!body || !clause) return false;

  const lines = body.split("\n").map(x => x.trim()).filter(Boolean);
  if (lines.length === 0) return true;

  const re = new RegExp("^" + escapeRegex(clause) + "\\s+");
  const firstIsOwnHeading = re.test(lines[0]);

  return firstIsOwnHeading && lines.length === 1;
}

function isHeadingOnlyAnnexChunk(body, annex) {
  if (!body || !annex) return false;

  const lines = body.split("\n").map(x => x.trim()).filter(Boolean);
  if (lines.length === 0) return true;

  const re = new RegExp("^" + escapeRegex(annex) + "\\b", "i");
  const firstIsOwnHeading = re.test(lines[0]);

  return firstIsOwnHeading && lines.length === 1;
}

// -------------------- metadata helpers --------------------
function buildBaseMetadata(itemJson) {
  const meta = {};

  if (itemJson.source != null) meta.source = itemJson.source;
  if (itemJson.blobType != null) meta.blobType = itemJson.blobType;
  if (itemJson.loc != null) meta.loc = itemJson.loc;

  if (meta.source == null) meta.source = "blob";
  if (meta.blobType == null) meta.blobType = "text/plain";
  if (meta.loc == null) meta.loc = {};

  return meta;
}

// -------------------- chunk body cleanup --------------------
function cleanChunkBody(body) {
  return normalizeText(
    (body || "")
      .replace(/\nContents\s*\n/gi, "\n")
      .replace(/\nForeword\s*\n/gi, "\n")
  );
}

// -------------------- n8n entrypoint --------------------
const input = items[0]?.json ?? {};
const raw = input.text ?? input.data ?? "";

const baseMeta = buildBaseMetadata(input);
const specMeta = extract3gppMetaFromFirstChars(raw, 4000);

// Clean document
let text = normalizeText(raw);
text = remove3gppRunningHeadersAndFooters(text);
text = dropFrontMatter(text);
text = removeResidualBoilerplate(text);
text = normalizeText(text);

// Split by headings
const sections = splitByHeadings(text);

// Make each clause/subclause its own chunk
const chunks = sizeControl(sections, {
  maxChars: 4500,
  overlapChars: 250,
}).filter(c => {
  if (c.header?.type === "clause") {
    return !isHeadingOnlyClauseChunk(c.body, c.header.clause);
  }
  if (c.header?.type === "annex") {
    return !isHeadingOnlyAnnexChunk(c.body, c.header.annex);
  }
  return true;
});

// Output LangChain-style docs
return chunks.map((c, idx) => {
  const metadata = {
    ...baseMeta,
    ...specMeta,
    chunk_index: idx,
  };

  if (c.header?.type === "clause") {
    metadata.section_type = "clause";
    metadata.clause = c.header.clause;
    metadata.clause_title = c.header.title;
  } else if (c.header?.type === "annex") {
    metadata.section_type = "annex";
    metadata.annex = c.header.annex;
    metadata.annex_type = c.header.annex_type;
    metadata.annex_title = c.header.title;
  } else {
    metadata.section_type = "unknown";
  }

  return {
    json: {
      content: cleanChunkBody(c.body),
      metadata,
    },
  };
});

const out = [];

// take the first (and usually only) incoming item from the upload form
const item = items[0];

// all uploaded files live in item.binary
const binaries = item.binary || {};

for (const key of Object.keys(binaries)) {
  const file = binaries[key];

  out.push({
    json: {
      originalKey: key,
      filename: file.fileName || key,
    },
    binary: {
      // normalize each file to a single binary key: "data"
      data: file,
    },
  });
}

return out;

// n8n Code node (JavaScript)
// Mode: Run Once for All Items
// Input: items[0].json.data = full internal policy text (all policies in one string)
// Output: one item per policy, with ONLY { text, metadata } and no duplicates

function chunkAndNormalizeInternalPolicies(fullText) {
  if (typeof fullText !== "string") {
    throw new Error("Expected items[0].json.data to be a string.");
  }

  const text = fullText.replace(/\r\n/g, "\n");

  // ---- Global metadata (stored once per policy in metadata) ----
  const version = (text.match(/Version:\s*([^\n]+)/i) || [])[1]?.trim() || null;
  const date = (text.match(/Date:\s*([^\n]+)/i) || [])[1]?.trim() || null;
  const scope = (text.match(/Scope:\s*([^\n]+)/i) || [])[1]?.trim() || null;

  // ---- Split into policy blocks (dynamic: supports any number of policies) ----
  const parts = text.split(/\n={10,}\n(?=POLICY\s+OP-SEC-\d+\n)/i);

  const policyBlocks = parts
    .map(p => p.trim())
    .filter(p => /^POLICY\s+OP-SEC-\d+\b/i.test(p));

  return policyBlocks.map((block) => {
    // ---- Extract per-policy metadata ----
    const idMatch = block.match(/^POLICY\s+(OP-SEC-\d+)\b/im);
    const titleMatch = block.match(/^\s*Title:\s*(.+)\s*$/im);
    const severityMatch = block.match(/^\s*Severity:\s*(.+)\s*$/im);

    const policyId = idMatch ? idMatch[1].toUpperCase() : "OP-SEC-UNKNOWN";
    const title = titleMatch ? titleMatch[1].trim() : "Untitled Policy";
    const severity = severityMatch ? severityMatch[1].trim() : "Unknown";

    // ---- Clean policy text (keep only meaningful content) ----
    let cleanedText = block
      // remove POLICY header + title + separator line
      .replace(/^POLICY\s+OP-SEC-\d+\s*\n/i, "")
      .replace(/^Title:\s*.*\n/i, "")
      .replace(/^-{10,}\n/, "")
      // remove any trailing END/==== blocks if they got attached
      .replace(/\n=+\nEND OF INTERNAL SECURITY POLICY\n=+\s*$/gi, "")
      .replace(/\n=+\s*$/g, "")
      .trim();

    // remove duplicated severity line from text (severity lives in metadata)
    cleanedText = cleanedText.replace(/\nSeverity:\s*.+\s*$/i, "").trim();

    return {
      text: cleanedText,
      metadata: {
        source_type: "internal_policy",
        policy_id: policyId,
        title,
        severity,
        version,
        date,
        scope,
      },
    };
  });
}

// ---- n8n entrypoint ----
const input = items[0]?.json?.data;
const normalized = chunkAndNormalizeInternalPolicies(input);

// n8n requires: [{ json: ... }, ...]
return normalized.map(obj => ({ json: obj }));

const out = [];

// take the first (and usually only) incoming item from the upload form
const item = items[0];

// all uploaded files live in item.binary
const binaries = item.binary || {};

for (const key of Object.keys(binaries)) {
  const file = binaries[key];

  out.push({
    json: {
      originalKey: key,
      filename: file.fileName || key,
    },
    binary: {
      // normalize each file to a single binary key: "data"
      data: file,
    },
  });
}

return out;

// -------------------- helpers --------------------
function normalizeText(s) {
  return (s || "")
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\u00a0/g, " ") // NBSP -> space
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

// O-RAN running header/footer remover
function removeORanRunningHeadersAndFooters(text) {
  if (typeof text !== "string") return text;
  let t = text.replace(/\r\n/g, "\n");

  // Repeated copyright/footer blocks
  t = t.replace(
    /\n\s*©\s*\d{4}\s+by\s+the\s+O-RAN\s+ALLIANCE(?:\s+e\.V\.)?[\s\S]{0,260}?\n/gi,
    "\n"
  );

  // Repeated document identifier line
  t = t.replace(
    /\n\s*O-RAN\.WG\d{1,2}\.(?:TR|TS)\.[A-Z0-9.-]+-v\d{2}\.\d{2}(?:\.\d{2})?\s*\n/gi,
    "\n"
  );

  // Looser doc-id-only variant
  t = t.replace(
    /\n\s*O-RAN\.WG\d{1,2}\.(?:TR|TS)\.[A-Z0-9.-]{6,}\s*\n/gi,
    "\n"
  );

  // Standalone page numbers
  t = t.replace(/\n\s*\d{1,4}\s*\n/g, "\n");

  // Cleanup
  t = t.replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
  return t;
}

// Drop front matter by starting at Clause 1 "Scope" if found
function dropFrontMatter(text) {
  const idx = text.search(/\n1\s+Scope\s*\n/i);
  if (idx > 0) return text.slice(idx).trim();
  return text;
}

// -------------------- metadata extraction --------------------
function pickORanTitleFromHead(head) {
  const lines = head
    .split("\n")
    .map((x) => x.replace(/\s+/g, " ").trim())
    .filter(Boolean);

  const isBad = (s) => {
    const t = (s || "").trim();
    if (!t) return true;

    // legal / boilerplate
    if (/^(copyright|©)\b/i.test(t)) return true;
    if (/^the copying or incorporation\b/i.test(t)) return true;
    if (/your use is subject\b/i.test(t)) return true;
    if (/all rights reserved\b/i.test(t)) return true;
    if (/register of associations|vat|bonn|germany|buschkauler/i.test(t)) return true;

    // avoid selecting the doc id itself
    if (/^O-RAN\.WG\d{1,2}\.(TR|TS)\./i.test(t)) return true;

    // too long to be a title line
    if (t.length > 220) return true;

    return false;
  };

  const looksLikeGroupLine = (t) => {
    const s = (t || "").trim();
    if (!s) return false;
    if (/^O-RAN\s+Work\s+Group\b/i.test(s)) return true;
    if (/\b(Work|Focus|Working)\s+Group\b/i.test(s)) return true;
    if (/\bGroup\)\s*$/i.test(s)) return true; // "(Security Work Group)"
    return false;
  };

  const isClauseLike = (t) => /^\d+(\.\d+)*\s+/.test((t || "").trim());

  // Join consecutive title lines (handles multi-line titles)
  const joinTitleLines = (startIdx, maxLines = 3) => {
    const parts = [];
    for (let k = startIdx; k < lines.length && parts.length < maxLines; k++) {
      const s = lines[k];

      if (isBad(s)) break;
      if (looksLikeGroupLine(s)) break;
      if (isClauseLike(s)) break;

      // Stop if we hit obvious section labels
      if (/^(abstract|foreword|introduction|contents|table of contents)\b/i.test(s)) break;

      parts.push(s);
    }

    if (parts.length === 0) return null;

    // Merge with spaces + fix “hyphen at line end” artifacts
    let title = parts.join(" ").replace(/\s+/g, " ").trim();
    title = title.replace(/-\s+/g, "-"); // e.g. "Log- Management" -> "Log-Management" (best effort)
    title = title.replace(/-\s+/g, "-"); // apply twice to be safe

    // Optional: if you dislike "Log-Management", you can turn hyphen+space into space:
    // title = title.replace(/-\s+/g, " ");

    return title.length >= 6 ? title : null;
  };

  // 1) Best: meaningfully close to "O-RAN Work Group ..."
  for (let i = 0; i < lines.length; i++) {
    if (/^O-RAN\s+Work\s+Group\b/i.test(lines[i])) {
      // Skip the group line and start scanning for the actual title
      for (let j = i + 1; j < Math.min(i + 10, lines.length); j++) {
        const cand = lines[j];
        if (isBad(cand)) continue;
        if (looksLikeGroupLine(cand)) continue;

        // Prefer "Study on ..." when present, and consider it start of multi-line title
        if (/^Study on\b/i.test(cand)) {
          const joined = joinTitleLines(j, 3);
          if (joined) return joined;
          return cand;
        }

        // Otherwise: first plausible title line becomes start of multi-line title
        if (cand.length >= 8 && cand.length <= 140) {
          const joined = joinTitleLines(j, 3);
          if (joined) return joined;
          return cand;
        }
      }
    }
  }

  // 2) Next best: any "Study on ..." near the top, join follow-up line(s)
  for (let i = 0; i < Math.min(lines.length, 80); i++) {
    const l = lines[i];
    if (isBad(l) || looksLikeGroupLine(l)) continue;
    if (/^Study on\b/i.test(l)) {
      const joined = joinTitleLines(i, 3);
      if (joined) return joined;
      return l;
    }
  }

  // 3) Fallback: first decent short line, join follow-ups
  for (let i = 0; i < Math.min(lines.length, 80); i++) {
    const l = lines[i];
    if (isBad(l) || looksLikeGroupLine(l) || isClauseLike(l)) continue;
    if (l.length >= 8 && l.length <= 140) {
      const joined = joinTitleLines(i, 2);
      if (joined) return joined;
      return l;
    }
  }

  return null;
}


function extractORanMeta(rawText, { headChars = 12000 } = {}) {
  const raw = (rawText || "").replace(/\r\n/g, "\n");
  const head = raw.slice(0, headChars);

  // Canonical doc-id (tight)
  const CANON_ID_RE =
    /\b(O-RAN\.WG(\d{1,2})\.(TR|TS)\.[A-Z0-9.-]+?-v(\d{2}\.\d{2}(?:\.\d{2})?))\b/i;

  // Spaced variant (OCR / extraction oddities)
  const SPACED_ID_RE =
    /\bO\s*-\s*RAN\s*\.?\s*WG\s*(\d{1,2})\s*\.?\s*(TR|TS)\s*\.?\s*([A-Z0-9.-]+?)\s*-?\s*v\s*(\d{2}\.\d{2}(?:\.\d{2})?)\b/i;

  let m = head.match(CANON_ID_RE);
  if (!m) m = raw.match(CANON_ID_RE);

  let doc_id = null,
    wg = null,
    doc_type = null,
    version = null;

  if (m) {
    doc_id = m[1];
    wg = m[2];
    doc_type = (m[3] || "").toUpperCase();
    version = m[4] || null;
  } else {
    const s = head.match(SPACED_ID_RE) || raw.match(SPACED_ID_RE);
    if (s) {
      wg = s[1];
      doc_type = (s[2] || "").toUpperCase();
      const body = (s[3] || "").replace(/\s+/g, "");
      version = s[4] || null;
      doc_id = `O-RAN.WG${wg}.${doc_type}.${body}-v${version}`;
    }
  }

  const title = pickORanTitleFromHead(head);

  return {
    source_type: "o_ran_spec",
    o_ran_doc_id: doc_id,
    o_ran_wg: wg ? `WG${wg}` : null,
    o_ran_doc_type: doc_type, // TR / TS
    o_ran_version: version ? `v${version}` : null,
    spec: doc_id || "O-RAN SPEC",
    title,
    meta_extracted_from: `head_${headChars}_chars_with_fulltext_fallback`,
  };
}

// -------------------- heading-based chunking --------------------
// Clause headings like: "5.3.2 Title..."
const CLAUSE_HEADING_RE =
  /(^|\n)(\d+(?:\.\d+){0,6})\s+([A-Z].{3,180})\s*(?=\n)/g;

// Annex headings like: "Annex A (normative): Title", "Annex A: Title", or "Annex:" then title next line
const ANNEX_HEADING_RE =
  /(^|\n)(Annex(?:\s+[A-Z]{1,3})?)\s*(?:\((normative|informative)\))?\s*(?::\s*([^\n]{0,220}))?\s*(?=\n)/gi;

function splitByHeadings(text) {
  const markers = [];

  CLAUSE_HEADING_RE.lastIndex = 0;
  for (let m; (m = CLAUSE_HEADING_RE.exec(text)) !== null; ) {
    const start = m.index + (m[1] ? m[1].length : 0);
    markers.push({ start, type: "clause", clause: m[2], title: m[3].trim() });
  }

  ANNEX_HEADING_RE.lastIndex = 0;
  for (let m; (m = ANNEX_HEADING_RE.exec(text)) !== null; ) {
    const start = m.index + (m[1] ? m[1].length : 0);
    const annexRaw = (m[2] || "Annex").replace(/\s+/g, " ").trim();
    const annex_type = (m[3] || "").toLowerCase() || null;
    const title = (m[4] || "").trim() || null;

    markers.push({
      start,
      type: "annex",
      annex: annexRaw,
      annex_type,
      title,
    });
  }

  if (markers.length === 0) return [{ header: null, body: text }];

  markers.sort((a, b) => a.start - b.start);

  const sections = [];
  for (let i = 0; i < markers.length; i++) {
    const cur = markers[i];
    const nextStart = i + 1 < markers.length ? markers[i + 1].start : text.length;
    let body = text.slice(cur.start, nextStart).trim();

    // If annex has no inline title, infer from next non-empty line
    if (cur.type === "annex" && (!cur.title || cur.title.length < 3)) {
      const lines = body.split("\n").map((x) => x.trim()).filter(Boolean);
      if (lines.length >= 2) {
        const possibleTitle = lines[1];
        if (!/^\d+(\.\d+)*\s+/.test(possibleTitle) && possibleTitle.length >= 3) {
          cur.title = possibleTitle;
        }
      }
    }

    const header =
      cur.type === "clause"
        ? { type: "clause", clause: cur.clause, title: cur.title }
        : { type: "annex", annex: cur.annex, annex_type: cur.annex_type, title: cur.title };

    sections.push({ header, body });
  }

  return sections;
}

function sizeControl(
  sections,
  { minChars = 900, maxChars = 4500, overlapChars = 250 } = {}
) {
  const merged = [];
  let buf = null;

  const flush = () => {
    if (buf) merged.push(buf);
    buf = null;
  };

  for (const sec of sections) {
    if (!buf) {
      buf = { header: sec.header, body: sec.body };
      continue;
    }

    if (buf.body.length < minChars) {
      buf.body = (buf.body + "\n\n" + sec.body).trim();
      continue;
    }

    flush();
    buf = { header: sec.header, body: sec.body };
  }
  flush();

  const final = [];
  for (const sec of merged) {
    if (sec.body.length <= maxChars) {
      final.push(sec);
      continue;
    }
    let start = 0;
    while (start < sec.body.length) {
      const end = Math.min(sec.body.length, start + maxChars);
      final.push({ header: sec.header, body: sec.body.slice(start, end).trim() });
      if (end === sec.body.length) break;
      start = Math.max(0, end - overlapChars);
    }
  }
  return final;
}

// -------------------- n8n entrypoint --------------------
const raw = items[0]?.json?.text ?? items[0]?.json?.extractedText ?? items[0]?.json?.data ?? "";

// Guard: raw PDF bytes accidentally passed in
if (typeof raw === "string" && raw.trimStart().startsWith("%PDF-")) {
  throw new Error("Input is raw PDF bytes (%PDF-...). Use an Extract Text From PDF step first.");
}

// Extract O-RAN metadata (robust)
const specMeta = extractORanMeta(raw, { headChars: 12000 });

// Clean + normalize
let text = normalizeText(raw);
text = removeORanRunningHeadersAndFooters(text);
text = dropFrontMatter(text);
text = normalizeText(text);

// Chunk
const sections = splitByHeadings(text);
const chunks = sizeControl(sections, { minChars: 900, maxChars: 4500, overlapChars: 250 });

// Output LangChain-style docs
return chunks.map((c, idx) => {
  const meta = { ...specMeta, chunk_index: idx };

  if (c.header?.type === "clause") {
    meta.section_type = "clause";
    meta.clause = c.header.clause;
    meta.clause_title = c.header.title;
  } else if (c.header?.type === "annex") {
    meta.section_type = "annex";
    meta.annex = c.header.annex;
    meta.annex_type = c.header.annex_type;
    meta.annex_title = c.header.title;
  } else {
    meta.section_type = "unknown";
  }

  return {
    json: {
      pageContent: c.body,
      metadata: meta,
    },
  };
});

