 *     original_config
 *     working_config
 *     fileName
 *     fileType
 *     network_function
 *     revisionIteration (optional)
 *     reflectionFeedback (optional)
 *     smf_integrity_policy (recommended)
 *     smf_confidentiality_policy (recommended)
 */

const items = $input.all();

// Helper: read policy values from multiple possible places/keys
function readIntegrity(j) {
  return (
    j?.smf_integrity_policy ??
    j?.["SMF Integrity Policy"] ??
    j?.body?.["SMF Integrity Policy"] ??
    j?.body?.smf_integrity_policy ??
    ""
  );
}

function readConfidentiality(j) {
  return (
    j?.smf_confidentiality_policy ??
    j?.["SMF Confidentiality Policy"] ??
    j?.["SMF Confidentiality Policy "] ?? // handles trailing-space key
    j?.body?.["SMF Confidentiality Policy"] ??
    j?.body?.["SMF Confidentiality Policy "] ??
    j?.body?.smf_confidentiality_policy ??
