  );
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // 1) Flatten LLM/Agent output if wrapped in { output: {...} }
  if (item.json?.output && typeof item.json.output === "object") {
    item.json = { ...item.json, ...item.json.output };
    delete item.json.output;
  }

  const hasBinaryFile = !!item.binary?.File;

  // ========= Iteration 1 =========
  if (hasBinaryFile) {
    const buffer = await this.helpers.getBinaryDataBuffer(i, "File");
    const configText = buffer.toString("utf8");

    // Initialize configs
    item.json.original_config = configText;
    item.json.working_config = configText;

    // Metadata
    item.json.fileName =
      item.json.fileName ?? item.binary.File.fileName ?? "unknown";

    item.json.fileType =
      item.json.fileType ?? item.json?.body?.file_type ?? "Configuration";

    item.json.network_function =
      item.json.network_function ??
      $input.first().json["Network Function Type/ Application"] ??
      "unknown";

    // Iteration
    item.json.revisionIteration = item.json.revisionIteration ?? 1;

    // No feedback on first pass
    item.json.reflectionFeedback = item.json.reflectionFeedback ?? "";

    // --- SMF policies: capture from upload form into normalized keys
    item.json.smf_integrity_policy = readIntegrity(item.json);
    item.json.smf_confidentiality_policy = readConfidentiality(item.json);
  } else {
    // ========= Iteration 2+ =========
    // --- SMF policies: carry forward if present; otherwise try to recover from any legacy keys
    item.json.smf_integrity_policy =
      item.json.smf_integrity_policy || readIntegrity(item.json);

    item.json.smf_confidentiality_policy =
      item.json.smf_confidentiality_policy || readConfidentiality(item.json);
  }

  // ========= Validate required fields (must exist every iteration) =========
  const missing = [];

  if (!item.json.original_config) missing.push("original_config");
  if (!item.json.working_config) missing.push("working_config");
  if (!item.json.fileName) missing.push("fileName");
  if (!item.json.fileType) missing.push("fileType");
  if (!item.json.network_function) missing.push("network_function");

