  // if (!item.json.smf_integrity_policy) missing.push("smf_integrity_policy");

  if (missing.length) {
    throw new Error(
      `Prepare Compliance Input: missing required fields: ${missing.join(
        ", "
      )}. Ensure 'Prepare Revision Input' sets them for loop iterations.`
    );
  }

  // Normalize optional fields
  item.json.revisionIteration = item.json.revisionIteration ?? 1;
  item.json.reflectionFeedback = item.json.reflectionFeedback ?? "";
  item.json.smf_integrity_policy = item.json.smf_integrity_policy ?? "";
